-- analytics views -------------------------------------------------------

CREATE VIEW v_variant_calls AS
SELECT
  sample.sample_code,
  subject.subject_code,
  gene.hgnc_symbol AS gene_symbol,
  variant.chromosome,
  variant.position,
  variant.reference_allele,
  variant.alternate_allele,
  variant.clinical_significance,
  call.genotype,
  call.alt_read_count,
  call.total_read_count,
  call.filter_status
FROM variant_calls call
JOIN samples sample ON sample.id = call.sample_id
JOIN subjects subject ON subject.id = sample.subject_id
JOIN variants variant ON variant.id = call.variant_id
JOIN genes gene ON gene.id = variant.gene_id;

CREATE VIEW v_sample_qc AS
SELECT
  sample.sample_code,
  sample.assay,
  sample.mean_coverage,
  sample.is_control,
  count(call.id) FILTER (WHERE call.filter_status = 'PASS') AS pass_call_count,
  count(call.id) FILTER (WHERE call.genotype <> '0/0') AS non_reference_call_count
FROM samples sample
LEFT JOIN variant_calls call ON call.sample_id = sample.id
GROUP BY sample.id, sample.sample_code, sample.assay, sample.mean_coverage, sample.is_control;

COMMENT ON SCHEMA genomics IS 'Synthetic clinical-genomics cohort for text-to-SQL evaluation. Real HGNC gene symbols, invented subjects, samples, variants and measurements. Not clinical data.';
COMMENT ON COLUMN variant_calls.genotype IS 'VCF genotype: 0/0 is homozygous reference (the sample does NOT carry the variant), 0/1 heterozygous, 1/1 homozygous alternate.';
COMMENT ON COLUMN gene_expression.tpm IS 'Transcripts per million. A value of 0 is a measured zero, not a missing value.';
COMMENT ON COLUMN variant_calls.read_depth IS 'Total depth at the site; identical to total_read_count in this fixture.';

COMMIT;
